class Job:
    def __init__(self, query, callback):
        self.query = query
        self.callback = callback
        self.cancel_count = 0

    def cancel(self):
        self.cancel_count += 1

    def deliver(self, value):
        # The transport can deliver late or duplicate callbacks after cancel.
        self.callback(value)


class Transport:
    def __init__(self):
        self.jobs = []

    def start(self, query, callback):
        # Callback delivery is deferred until Job.deliver; start never raises.
        job = Job(query, callback)
        self.jobs.append(job)
        return job

class Screen:
    def __init__(self, transport, on_value):
        self.transport = transport
        self.on_value = on_value

    def search(self, query):
        raise NotImplementedError

    def close(self):
        raise NotImplementedError
